# Helpers
exceptions = []
def log(case_ref, table, column, value, issue, severity="ACTION"):
    exceptions.append({"severity": severity, "caseReference": case_ref, "table": table, "column": column,
                       "value": None if value is None else str(value)[:300], "issue": issue})

extra_notes = []   # text found in date fields etc, moved to S62aCaseNote

def blank(v):
    return v is None or (isinstance(v, float) and pd.isna(v)) or str(v).strip() in ("", "nan", "NaT", "None")

def clean(v):
    if blank(v):
        return None
    if isinstance(v, str):
        v = v.strip()
        if FLATTEN_NEWLINES:
            v = re.sub(r"\s*[\r\n]+\s*", " | ", v)
    return v

DATE_IN_TEXT = re.compile(r"\b(\d{1,2}/\d{1,2}/\d{2,4})\b")

def to_date(v, ref=None, table=None, col=None):
    if blank(v):
        return None
    if isinstance(v, (datetime, pd.Timestamp)):
        return pd.Timestamp(v).strftime("%Y-%m-%d")
    text = str(v).strip()
    d = pd.to_datetime(text, dayfirst=True, errors="coerce")
    if not pd.isna(d):
        return d.strftime("%Y-%m-%d")
    m = DATE_IN_TEXT.search(text)
    if m:
        d = pd.to_datetime(m.group(1), dayfirst=True, errors="coerce")
        if not pd.isna(d):
            extra_notes.append({"caseReference": ref, "noteType": col, "noteText": f"{col}: {clean(text)}"})
            log(ref, table, col, v, "Date taken from text, full text kept in S62aCaseNote", "INFO")
            return d.strftime("%Y-%m-%d")
    if KEEP_DATELESS_TEXT_AS_NOTE:
        extra_notes.append({"caseReference": ref, "noteType": col, "noteText": f"{col}: {clean(text)}"})
        log(ref, table, col, v, "No date in value, set to null, text kept in S62aCaseNote", "INFO")
    else:
        log(ref, table, col, v, "No date in value, set to null, text removed", "INFO")
    return None

def split_multi(v):
    """'[a, b]' or '{a, b}' -> ['a','b'];  'a; b' -> ['a','b'];  scalar -> [scalar]."""
    if blank(v):
        return []
    s = str(v).strip()
    m = re.match(r"^[\[{](.*)[\]}]$", s, re.S)
    if m:
        return [x.strip() or None for x in m.group(1).split(",")]
    if ";" in s:
        return [x.strip() or None for x in s.split(";")]
    return [v]

def is_date_field(name):
    return bool(re.search(r"date$|Date$", str(name)))

def get(row, col):
    return row[col] if col in row.index else None

# Case scope (+ generate references for rows without one)
generated_refs = []
if GENERATE_MISSING_REFS:
    existing = set(src["Case reference"])
    missing = src[~src["Case reference"].str.match(REF_PATTERN)].copy()

    def ref_year(row):
        for c in REF_YEAR_COLUMNS:
            v = get(row, c)
            if not blank(v):
                d = pd.to_datetime(v, dayfirst=True, errors="coerce")
                if not pd.isna(d):
                    return d.year, c, d
        return None, None, None

    missing[["_year", "_year_from", "_year_date"]] = missing.apply(lambda r: pd.Series(ref_year(r)), axis=1)
    counters = {}
    running = max([int(r[-4:]) for r in existing if re.match(r"^S62A/\d{4}/\d{4}$", r)] or [0]) + 1
    for idx, row in missing.sort_values(["_year_date"], na_position="last").iterrows():
        original = row["Case reference"]
        if pd.isna(row._year):
            log(original, "scope", "Case reference", original, "No valid reference and no date to build one from, excluded")
            continue
        year = int(row._year)
        n = running if GENERATED_REF_MODE == "continue" else counters.get(year, GENERATED_REF_START)
        while f"S62A/{year}/{n:04d}" in existing:
            n += 1
        new_ref = f"S62A/{year}/{n:04d}"
        existing = existing | {new_ref}
        if GENERATED_REF_MODE == "continue":
            running = n + 1
        else:
            counters[year] = n + 1
        src.at[idx, "Case reference"] = new_ref
        if "Historical reference" not in src.columns or blank(src.at[idx, "Historical reference"]):
            src.at[idx, "Historical reference"] = original
        generated_refs.append({"originalValue": original, "generatedReference": new_ref,
                               "yearFrom": row._year_from, "yearDate": row._year_date.strftime("%Y-%m-%d")})
        log(new_ref, "scope", "Case reference", original,
            f"Generated reference {new_ref} (year from {row._year_from}), original kept in historicalReference", "INFO")

src["_ref_class"] = src["Case reference"].map(
    lambda r: "INVALID" if not re.match(REF_PATTERN, r)
    else "PRE_APP" if len(re.match(REF_PATTERN, r).group(2)) == 7 else "APPLICATION")
for r in src.loc[src._ref_class == "INVALID", "Case reference"]:
    if not GENERATE_MISSING_REFS:
        log(r, "scope", "Case reference", r, "No valid reference, excluded")
cases = src[src._ref_class != "INVALID"].reset_index(drop=True)
print(f"In scope: {len(cases)} | excluded: {(src._ref_class == 'INVALID').sum()} | generated refs: {len(generated_refs)}")
for g in generated_refs:
    print(f"  {g['generatedReference']}  <-  {g['originalValue'][:60]}  ({g['yearFrom']} {g['yearDate']})")

# 1b. Notes: one row per note column with a value
note_rows = []
for _, row in cases.iterrows():
    for c in note_cols:
        v = get(row, c)
        if not blank(v):
            text = clean(to_date(v) if isinstance(v, (datetime, pd.Timestamp)) else v)
            note_rows.append({"caseReference": row["Case reference"], "noteType": c, "noteText": f"{c}: {text}"})

# 3. Contacts + addresses (agent, applicant, site). Multiple people per cell split on ';'
contact_rows, address_rows = [], []
for _, row in cases.iterrows():
    ref = row["Case reference"]
    for role in ["Agent", "Applicant"]:
        parts = {k: split_multi(get(row, f"{role} {k}")) for k in ["first name", "last name", "email", "phone"]}
        org = get(row, f"{role} organisation name")
        n = max([len(v) for v in parts.values()] + [1 if not blank(org) else 0])
        lens = {k: len(v) for k, v in parts.items() if len(v) > 1}
        if len(set(lens.values())) > 1:
            log(ref, "Contact", role, lens, "Multi-person cells have different counts, aligned by position")
        for i in range(n):
            pick = lambda k: parts[k][i] if i < len(parts[k]) else None
            email = pick("email")
            contact_rows.append({
                "caseReference": ref, "contactRole": role, "sequence": i + 1,
                "orgName": clean(org) if i == 0 else None,
                "firstName": clean(pick("first name")), "lastName": clean(pick("last name")),
                "email": clean(re.sub(r"^mailto:", "", str(email), flags=re.I)) if not blank(email) else None,
                "telephoneNumber": clean(pick("phone")),
                "applicantType": clean(get(row, "Applicant type")) if role == "Applicant" and i == 0 else None,
            })
    for role, cols in {
        "Agent":     ["Agent address 1", "Agent address 2", "Agent town or city", "Agent county", "Agent postcode"],
        "Applicant": ["Applicant address 1", "Applicant address 2", "Applicant town or city", "Applicant county", "Applicant postcode"],
        "Site":      ["Site address 1", "Site address 2", "Site town or city", "Site county", "Site post code"],
    }.items():
        vals = [clean(get(row, c)) for c in cols]
        if any(v is not None for v in vals):
            address_rows.append(dict(zip(["caseReference", "addressType", "line1", "line2", "townCity", "county", "postcode"],
                                         [ref, role] + vals)))
tables["Contact"] = contact_rows
tables["Address"] = address_rows

# 5. Events (one row per event type that has data)
EVENTS = {
    "SiteVisit":         {"Site visit type": "siteVisitType", "Site visit date": "eventDate"},
    "ProcedureNotice":   {"Notice of procedure date": "eventDate"},
    "Hearing":           {"Hearing  date": "eventDate", "Hearing notification date": "notificationDate",
                          "Hearing issues report published date": "issuesReportPublishedDate",
                          "Hearing duration - prep (days)": "prepDuration",
                          "Hearing duration - sitting (days)": "sittingDuration",
                          "Hearing duration - reporting (days)": "reportingDuration", "Hearing venue": "venue"},
    "AdditionalMeeting": {"Additional meeting required date": "eventDate"},
}
event_rows = []
for _, row in cases.iterrows():
    for etype, cols in EVENTS.items():
        if all(blank(get(row, c)) for c in cols):
            continue
        rec = {"caseReference": row["Case reference"], "eventType": etype}
        for c, f in cols.items():
            v = get(row, c)
            rec[f] = to_date(v, row["Case reference"], "S62aEvent", c) if "Date" in f or f == "eventDate" else clean(v)
        event_rows.append(rec)
tables["S62aEvent"] = event_rows

# 6. Repeating groups: explode '[a, b]' / '{a, b}' cells into child rows
def derive_parking(lists, ambiguous, n):
    """existing + difference = proposed, so a missing one can be rebuilt when the other two line up."""
    def nums(f):
        v = lists.get(f, [])
        try:
            return [float(x) for x in v] if len(v) == n and f not in ambiguous else None
        except (TypeError, ValueError):
            return None
    rules = {"existingSpaces":  lambda p, e, d: [a - b for a, b in zip(p, d)] if p and d else None,
             "proposedSpaces":  lambda p, e, d: [a + b for a, b in zip(e, d)] if e and d else None,
             "spaceDifference": lambda p, e, d: [a - b for a, b in zip(p, e)] if p and e else None}
    resolved = {}
    for f, rule in rules.items():
        if f not in ambiguous:
            continue
        derived = rule(nums("proposedSpaces"), nums("existingSpaces"), nums("spaceDifference"))
        original = {float(x) for x in ambiguous[f] if not blank(x)}
        if derived and original <= set(derived):
            resolved[f] = [int(x) if x == int(x) else x for x in derived]
    return resolved

COUNT_FIELDS = {"existingSpaces", "proposedSpaces", "spaceDifference", "bedroomsOne", "bedroomsTwo", "bedroomsThree",
                "bedroomsFourPlus", "bedroomsUnknown", "totalUnits", "netAdditionalGross", "existingGross",
                "grossLost", "grossProposed", "voidCapacity", "maxAnnualThroughput"}

def explode_group(table, cols, extra=None, derive=None):
    """Horizon joins each attribute as a DISTINCT list with nulls dropped, so values can only be
    matched to groups when an attribute has one value per group. Anything else is ambiguous:
    left null and logged, to be fixed from row-level Horizon data."""
    rows = []
    id_col = "groupId" if "groupId" in cols.values() else None
    for _, row in cases.iterrows():
        ref = row["Case reference"]
        lists = {f: split_multi(get(row, c)) for c, f in cols.items()}
        n = (len(lists[id_col]) if id_col else 0) or max(len(v) for v in lists.values())
        if n == 0:
            continue
        ambiguous = {f: v for f, v in lists.items() if f != id_col and 0 < len(v) != n}
        if derive and ambiguous:
            for f, vals in derive(lists, ambiguous, n).items():
                log(ref, table, f, ambiguous.pop(f), f"Rebuilt from the other parking columns: {vals}", "INFO")
                lists[f] = vals
        for f, v in ambiguous.items():
            filled = "set to 0" if NULL_COUNTS_TO_ZERO and f in COUNT_FIELDS else "left null"
            log(ref, table, f, get(row, next(c for c, ff in cols.items() if ff == f)),
                f"Ambiguous: {len(v)} value(s) for {n} groups, {filled}; source value not migrated (check Horizon)")
        for i in range(n):
            rec = {"caseReference": ref, "sequence": i + 1, **(extra or {})}
            for f, vals in lists.items():
                rec[f] = clean(vals[i]) if f not in ambiguous and i < len(vals) else None
            if any(rec[f] is not None for f in lists if f != id_col) or ambiguous:
                if NULL_COUNTS_TO_ZERO:
                    for f in lists:
                        if f in COUNT_FIELDS and rec[f] is None:
                            rec[f] = 0
                rows.append(rec)
    return rows

tables["S62aVehicleParking"] = explode_group("S62aVehicleParking", {
    "ParkingGroupID": "groupId", "ParkingVehicleType": "vehicleType", "ParkingExistingSpaces": "existingSpaces",
    "ParkingProposedSpaces": "proposedSpaces", "ParkingSpaceDifference": "spaceDifference"},
    derive=derive_parking)

tables["S62aNonResidentialFloorspace"] = explode_group("S62aNonResidentialFloorspace", {
    "NonResGroupID": "groupId", "UseClass": "useClass", "FloorspaceChange": "netAdditionalGross",
    "ExistingFloorspaceSqM": "existingGross", "FloorspaceLostSqM": "grossLost", "FloorspaceProposedSqM": "grossProposed"})

housing = []
for htype in ["Existing", "Proposed"]:
    housing += explode_group("S62aResidentialHousing", {
        f"{htype}HousingGroupID": "groupId", f"{htype}HousingOccupancyType": "occupancyType",
        f"{htype}HousingUnitType": "unitType", f"{htype}Housing1BedCount": "bedroomsOne",
        f"{htype}Housing2BedCount": "bedroomsTwo", f"{htype}Housing3BedCount": "bedroomsThree",
        f"{htype}Housing4PlusBedCount": "bedroomsFourPlus", f"{htype}HousingUnknownBedCount": "bedroomsUnknown",
        f"{htype}HousingTotalUnits": "totalUnits"}, extra={"housingType": htype})
tables["S62aResidentialHousing"] = housing

tables["S62aCaseWasteType"] = explode_group("S62aCaseWasteType", {
    "WasteType": "wasteType", "VoidCapacityCubicMetres": "voidCapacity",
    "LiquidWasteMaxAnnualThroughput": "maxAnnualThroughput", "WasteMaxThroughputType": "maxThroughputType"})

# 9. Write one CSV per table
out_dir = os.path.join(TMP if not LOCAL_DIR else ".", f"s62a_transform_{RUN_TS}")
os.makedirs(out_dir, exist_ok=True)
files = {f"{t}.csv": pd.DataFrame(r) for t, r in tables.items()}
files["_exceptions.csv"] = exceptions_df
files["_relationships.csv"] = relationships_df
gen_df = pd.DataFrame(generated_refs, columns=["originalValue", "generatedReference", "yearFrom", "yearDate"])
gen_df.insert(0, "caseId", gen_df["generatedReference"].map(case_ids))
files["_generated_references.csv"] = gen_df
files["_summary.csv"] = summary
for name, frame in files.items():
    frame.to_csv(os.path.join(out_dir, name), index=False, encoding="utf-8", quoting=csv.QUOTE_MINIMAL)

if LOCAL_DIR:
    print(f"Written to {out_dir}")
else:
    for folder in (RUN_TS, "latest"):
        dest = f"{LOC['root']}/{LOC['output']}/{folder}"
        if folder == "latest":
            try:
                mssparkutils.fs.rm(dest, True)
            except Exception:
                pass
        for name in files:
            mssparkutils.fs.cp(f"file:{os.path.join(out_dir, name)}", f"{dest}/{name}")
        print(f"Written to {dest}")
